diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -2513,7 +2513,12 @@

   // whether or not the request succeeds, `len` seems to be the app's preferred
   // buffer fill size; remember it.
-  parser->m_lastBufferRequestSize = len;
+  const bool repeatedEmptyRequest
+      = parser->m_buffer != NULL && parser->m_bufferPtr == parser->m_buffer
+        && parser->m_bufferEnd == parser->m_buffer
+        && parser->m_lastBufferRequestSize == len;
+  parser->m_lastBufferRequestSize
+      = len + (repeatedEmptyRequest && len < INT_MAX);
   if (len > EXPAT_SAFE_PTR_DIFF(parser->m_bufferLim, parser->m_bufferEnd)
       || parser->m_buffer == NULL) {
     /* Do not invoke signed arithmetic overflow: */

diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -2441,7 +2441,10 @@

   start = parser->m_bufferPtr;
   parser->m_positionPtr = start;
-  parser->m_bufferEnd += len;
+  parser->m_bufferEnd
+      += (len == EXPAT_SAFE_PTR_DIFF(parser->m_bufferLim, parser->m_bufferEnd))
+             ? parser->m_lastBufferRequestSize
+             : len;
   parser->m_parseEndPtr = parser->m_bufferEnd;
   parser->m_parseEndByteIndex += len;
   parser->m_parsingStatus.finalBuffer = (XML_Bool)isFinal;
